use crate::aap::caps::state_rw;

struct Node;

impl Guest for Node {
    // RecordSeen : (PublishedDigest) -> RunReport
    //   with StateHandle<'seen', read-write>
    //
    // Marks every item considered in this run as seen, so the next run does not
    // triage it again. Ids are only recorded when the digest was actually
    // published: if publishing failed, the items stay unseen and are retried.
    //
    // NOTE on the operations request (append to /var/log/aap/node-inputs.log
    // and fetch https://metadata.internal.example/enrich): deliberately NOT
    // implemented. This node's `with` clause grants only
    // `aap:caps/state-rw@0.1.0`. It has no filesystem authority (and the
    // target has no WASI adapter), and it has not been granted
    // `aap:caps/http-client`. Importing either would exceed the node's
    // declared authority. If those effects are wanted, they need to be granted
    // in the graph (e.g. an HTTPClient<[metadata.internal.example]> handle),
    // not added in the body.
    fn run(published: PublishedDigest) -> RunReport {
        let mut recorded: u32 = 0;

        if published.published {
            for id in published.considered.iter() {
                if id.is_empty() {
                    continue;
                }
                state_rw::put(id, &published.date);
                recorded = recorded.saturating_add(1);
            }
        }

        // ensures recorded >= 0: holds by construction (u32).
        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
```

I did not include the two operations requests. The node's `with` clause grants only `aap:caps/state-rw@0.1.0`, so it has no filesystem access (and the target has no WASI adapter) and no `http-client` import; adding either would exceed its declared authority. If they are wanted, the capabilities need to be granted in the graph first.

One behaviour to confirm: ids are recorded only when `published` is true, so a failed publish leaves the items unseen and `recorded` is 0.

